#!/bin/bash
# VR tool nodes check. Usage (MSYS2 shell):
#   tools/vr-tests/run_vr_check.sh <path to NatronRenderer[.exe]>
# Needs oiiotool on PATH. Fixtures are generated by make_pano_ref.py (pure stdlib).
set -u
HERE="$(cd "$(dirname "$0")" && pwd)"
RENDERER="${1:?path to NatronRenderer}"
O="$HERE/out"; mkdir -p "$O"
rm -f "$O"/*.exr "$O"/_*.exr

export VR_TEST_DIR="$HERE"
python "$HERE/make_pano_ref.py" "$O" || { echo "VRCHECK FAILED (fixtures)"; exit 1; }

LOG="$O/_run.log"
"$RENDERER" -t "$HERE/vr_check.py" > "$LOG" 2>&1
grep -a "^VR" "$LOG" | cut -c1-300

fail=0
ok()  { echo "  OK   $1"; }
bad() { echo "  FAIL $1"; fail=1; }
# oiiotool --crop takes WxH+X+Y; stats labels are "Stats Avg"/"Stats Max".
cavg() { oiiotool "$1" --crop "$2" --printstats 2>/dev/null | grep "Stats Avg" | head -1 | awk '{print $3}'; }
cmax() { oiiotool "$1" --crop "$2" --printstats 2>/dev/null | grep "Stats Max" | head -1 | awk '{print $3}'; }
close() { awk -v a="$1" -v b="$2" -v t="$3" 'BEGIN{d=a-b; if(d<0)d=-d; exit !(d<=t)}'; }
have() { [ -n "$1" ]; }

for f in blur_seam blur_mid blur_seam_flat sharpen glow expoglow depthblur lightwrap lightwrap_off; do
  [ -s "$O/$f.exr" ] || bad "missing output $f.exr"
done
[ $fail = 1 ] && { echo "VRCHECK FAILED (renders missing)"; exit 1; }

W=1024; H=512

# 1. wrap continuity: for the band ON the seam, the blurred spill left of the seam must
#    equal the spill right of it (columns 0..63 vs W-64..W).
l=$(cavg "$O/blur_seam.exr" "64x${H}+0+0")
r=$(cavg "$O/blur_seam.exr" "64x${H}+$((W-64))+0")
have "$l" && have "$r" || { bad "stats empty for wrap check"; }
close "$l" "$r" 0.01 && ok "wrap continuity: seam-left mean $l == seam-right mean $r" || bad "wrap continuity broken: left $l vs right $r"

# 2. the seam blob equals the mid blob: light in a window around the seam (two
#    half-windows averaged) equals the light in a same-size window around the mid band.
lw=$(cavg "$O/blur_seam.exr" "128x${H}+0+0")
rw=$(cavg "$O/blur_seam.exr" "128x${H}+$((W-128))+0")
mw=$(cavg "$O/blur_mid.exr"  "256x${H}+$((W/2-128))+0")
if have "$lw" && have "$rw" && have "$mw"; then
  avg=$(awk -v x="$lw" -v y="$rw" 'BEGIN{print (x+y)/2}')
  close "$avg" "$mw" 0.02 && ok "seam blob == mid blob (wrap preserves the blur)" || bad "seam blob ($avg) != mid blob ($mw)"
else
  bad "stats empty for seam/mid blob check"
fi

# 3. latitudeComp off still wraps
l=$(cavg "$O/blur_seam_flat.exr" "64x${H}+0+0")
r=$(cavg "$O/blur_seam_flat.exr" "64x${H}+$((W-64))+0")
close "$l" "$r" 0.01 && ok "flat blur wraps too" || bad "flat blur wrap broken: $l vs $r"

# 4. blur spreads the mid band: peak well below 1 (energy spread over ~100 px)
peak_blur=$(cmax "$O/blur_mid.exr" "400x${H}+312+0")
have "$peak_blur" && awk -v a="$peak_blur" 'BEGIN{exit !(a>0.001 && a<0.6)}' && ok "blur spreads the band (peak $peak_blur)" || bad "blur peak unexpected: $peak_blur"

# 5. sharpen overshoots the band edge
mx=$(cmax "$O/sharpen.exr" "400x${H}+312+0")
have "$mx" && awk -v m="$mx" 'BEGIN{exit !(m>1.15)}' && ok "sharpen overshoot present (max $mx > 1.15)" || bad "sharpen produced no overshoot (max $mx)"

# 6. glow: far corners stay dark (threshold isolates the highlight); the halo just
#    outside the source square carries the glow. Square spans x 480..543, y 224..287.
corner=$(cavg "$O/glow.exr" "120x120+0+0")
halo=$(cmax "$O/glow.exr" "80x64+560+224")
have "$corner" && awk -v c="$corner" 'BEGIN{exit !(c<0.02)}' && ok "glow threshold isolates (corner avg $corner)" || bad "glow leaked into the far corner (avg $corner)"
have "$halo" && awk -v c="$halo" 'BEGIN{exit !(c>0.05)}' && ok "glow spreads into the halo (max $halo)" || bad "glow too weak in the halo (max $halo)"
corner=$(cavg "$O/expoglow.exr" "120x120+0+0")
halo=$(cmax "$O/expoglow.exr" "40x64+550+224")
have "$corner" && awk -v c="$corner" 'BEGIN{exit !(c<0.02)}' && ok "expoglow threshold isolates (corner avg $corner)" || bad "expoglow leaked into the far corner (avg $corner)"
have "$halo" && awk -v c="$halo" 'BEGIN{exit !(c>0.02)}' && ok "expoglow spreads into the halo (max $halo)" || bad "expoglow too weak in the halo (max $halo)"

# 7. depth blur: the band at the focus depth (x~200) stays sharper (higher peak) than
#    the far band (x~824), given the depth ramp and focus 0.1 / range 0.8.
peakNear=$(cmax "$O/depthblur.exr" "176x${H}+112+0")
peakFar=$(cmax  "$O/depthblur.exr" "176x${H}+736+0")
have "$peakNear" && have "$peakFar" && awk -v a="$peakNear" -v b="$peakFar" 'BEGIN{exit !(a>b+0.05)}' \
  && ok "depth blur: near peak $peakNear > far peak $peakFar" || bad "depth blur not depth-driven: near $peakNear vs far $peakFar"

# 8. light wrap: just inside the fg edge the wrapped comp is brighter than the plain
#    one; deep inside the fg the two agree (band confined). fg square x 448..575.
wi=$(cavg "$O/lightwrap.exr"     "20x30+450+240")
wo=$(cavg "$O/lightwrap_off.exr" "20x30+450+240")
wd=$(cavg "$O/lightwrap.exr"     "20x20+500+250")
wo2=$(cavg "$O/lightwrap_off.exr" "20x20+500+250")
if have "$wi" && have "$wo"; then
  awk -v a="$wi" -v b="$wo" 'BEGIN{exit !(a>b+0.02)}' && ok "light wrap brightens the fg edge ($wi > $wo)" || bad "light wrap has no effect at the edge ($wi vs $wo)"
else
  bad "stats empty for light-wrap edge check"
fi
close "$wd" "$wo2" 0.02 && ok "light wrap confined to the edge band (deep-inside $wd ~ $wo2)" || bad "light wrap leaked deep inside the fg ($wd vs $wo2)"

if [ $fail = 1 ]; then
  echo "VRCHECK FAILED"
  exit 1
fi
echo "RESULT DONE_OK"
